/**
 * Extended kernel-level golden tests (P023 T011, S4).
 *
 * Thirteen hand-derived cases over the resolver kernel, covering policy
 * combinations, ADR-006 (DISCOVERED / DISABLED never leak), namespace
 * exactness,
 * the INCOMPLETE > FAIL > PASS precedence, discovery-skip findings, and
 * the Claude / OpenMausBot paths. Inputs are built synthetically in
 * this file; expectations live in ./extended/expected.json and were
 * worked out by hand from PROJECT_BOOK §4.1/§4.2 and ADR-005/ADR-006 —
 * they were NEVER generated by running the production resolver.
 *
 * Finding detail text is deliberately NOT part of the frozen contract
 * here: it is implementation wording (the kernel's policy wording
 * differs from the Oracle's by design, ADR-005). The comparison covers
 * id, severity, sourceScope, status, instanceIds and affectedCount, and
 * separately asserts every finding detail is non-empty.
 */

import { createHash } from "node:crypto";
import * as fs from "node:fs";
import * as path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

import type { CodexPocResult, CodexPocSkill } from "../../src/adapters/codex/codex-poc.js";
import type { ClaudePocResult } from "../../src/adapters/claude/claude-poc.js";
import type { OpenMausBotPocResult } from "../../src/adapters/openmausbot/openmausbot-poc.js";
import type { SkillInstanceV1 } from "../../src/contracts/index.js";
import type { PolicyV1 } from "../../src/policy/index.js";
import {
  resolveClaudeAudit,
  resolveCodexAudit,
  resolveOpenMausBotAudit,
  type AuditResult,
  type DiscoveryInput,
} from "../../src/resolver/index.js";

const HERE = path.dirname(fileURLToPath(import.meta.url));

interface ExpectedCase {
  case_id: string;
  engine: string;
  description: string;
  expected: {
    status: string;
    findings: Array<{
      id: string;
      severity: string;
      sourceScope: string;
      status: string;
      instanceIds: string[];
      affectedCount: number | null;
    }>;
    policy: { applied: boolean; effectiveCount: number; expectedCount: number; violationCount: number };
    coverage: { enumeratedSources: number; requiredSources: number; unknownScopes: string[] };
    instanceCount: number;
  };
}

const expectedDoc = JSON.parse(
  fs.readFileSync(path.join(HERE, "extended", "expected.json"), "utf8"),
) as { seed: string; cases: ExpectedCase[] };
const expectedById = new Map(expectedDoc.cases.map((c) => [c.case_id, c]));

function sha256(text: string): string {
  return createHash("sha256").update(text, "utf8").digest("hex");
}

// ------------------------------------------------------------ input builders ---

type CodexScope = "REPO" | "USER" | "ADMIN" | "SYSTEM" | "PLUGIN";

function codexSkill(overrides: {
  name: string;
  scope: CodexScope;
  status?: CodexPocSkill["status"];
  logicalName?: string;
  content?: string;
}): CodexPocSkill {
  const name = overrides.name;
  const scope = overrides.scope;
  const logicalName = overrides.logicalName ?? name;
  const relativePath = `${name.replace(":", "-")}/SKILL.md`;
  return {
    instanceId: `native-${scope.toLowerCase()}-${name}`,
    sourceRootId: scope.toLowerCase(),
    sourceScope: scope,
    relativePath,
    canonicalPath: `layout/${scope.toLowerCase()}/${relativePath}`,
    logicalName,
    folderName: name,
    contentSha256: sha256(overrides.content ?? `content-${name}`),
    canonicalPathHash: sha256(`path-${relativePath}`),
    status: overrides.status ?? "ELIGIBLE",
    aliases: [],
    evidenceLevel: "STATIC_RULE",
  };
}

function codexResult(overrides: {
  caseId: string;
  skills: CodexPocSkill[];
  findings?: CodexPocResult["findings"];
  enumerated?: number;
  required?: number;
  unknownSources?: CodexScope[];
  configReadable?: boolean;
}): CodexPocResult {
  return {
    schema: "skillscope.codex-poc-result/v1",
    caseId: overrides.caseId,
    status: "PASS",
    skills: overrides.skills,
    findings: overrides.findings ?? [],
    coverage: {
      enumeratedSources: overrides.enumerated ?? 5,
      requiredSources: overrides.required ?? 5,
    },
    unknownSources: overrides.unknownSources ?? [],
    configReadable: overrides.configReadable ?? true,
  };
}

function contractInstance(overrides: {
  engine: "claude-code" | "openmausbot";
  sourceRootId: string;
  sourceScope: string;
  name: string;
  status?: SkillInstanceV1["status"];
}): SkillInstanceV1 {
  const relativePath = `${overrides.name}/SKILL.md`;
  return {
    instanceId: `${overrides.sourceRootId}:${relativePath}`,
    engine: overrides.engine,
    sourceRootId: overrides.sourceRootId,
    sourceScope: overrides.sourceScope,
    relativePath,
    canonicalPathHash: sha256(`path-${overrides.sourceRootId}-${overrides.name}`),
    logicalName: overrides.name,
    folderName: overrides.name,
    contentSha256: sha256(`content-${overrides.sourceRootId}-${overrides.name}`),
    status: overrides.status ?? "ELIGIBLE",
    evidenceLevel: "STATIC_RULE",
  };
}

// ------------------------------------------------------------------ the cases ---

interface CaseRun {
  result: AuditResult;
}

function runCase(caseId: string): CaseRun {
  switch (caseId) {
    case "x01": {
      const poc = codexResult({
        caseId: "x01",
        skills: [
          codexSkill({ name: "release", scope: "REPO" }),
          codexSkill({ name: "deploy", scope: "PLUGIN" }),
          codexSkill({ name: "notes", scope: "USER" }),
        ],
      });
      const policy: PolicyV1 = { forbiddenScopes: ["PLUGIN"], forbiddenNames: ["release"] };
      return { result: resolveCodexAudit(poc, policy) };
    }
    case "x02": {
      // The Codex PoC type cannot express DISCOVERED (it only ever
      // reports ELIGIBLE / DISABLED / UNKNOWN), so the ADR-006 case runs
      // on the Claude path, where DISCOVERED is a real PoC status.
      const native: ClaudePocResult = {
        profileId: "x02",
        engine: "claude-code",
        instances: [
          contractInstance({ engine: "claude-code", sourceRootId: "plugin", sourceScope: "PLUGIN", name: "deploy", status: "DISCOVERED" }),
          contractInstance({ engine: "claude-code", sourceRootId: "user", sourceScope: "USER", name: "notes" }),
        ],
        findings: [],
        coverage: { enumeratedSources: 3, requiredSources: 3, unknownScopes: [] },
        status: "PASS",
      };
      return { result: resolveClaudeAudit(native, { forbiddenScopes: ["PLUGIN"] }) };
    }
    case "x03": {
      const poc = codexResult({
        caseId: "x03",
        skills: [
          codexSkill({ name: "acme-deploy", scope: "PLUGIN", logicalName: "acme:deploy" }),
          codexSkill({ name: "deploy", scope: "REPO" }),
        ],
      });
      return { result: resolveCodexAudit(poc, { forbiddenNames: ["deploy"] }) };
    }
    case "x04": {
      const poc = codexResult({
        caseId: "x04",
        skills: [
          codexSkill({ name: "release", scope: "REPO" }),
          codexSkill({ name: "deploy", scope: "PLUGIN" }),
        ],
      });
      return { result: resolveCodexAudit(poc, { allowedScopes: ["REPO"] }) };
    }
    case "x05": {
      const poc = codexResult({
        caseId: "x05",
        skills: [codexSkill({ name: "release", scope: "REPO" })],
        findings: [
          { id: "SOURCE_NOT_ENUMERATED", severity: "P1", sourceScope: "USER", status: "UNKNOWN", detail: "required source USER could not be enumerated" },
          { id: "NAME_SELECTOR_BLAST_RADIUS", severity: "P1", sourceScope: "GLOBAL", status: "CONFIRMED", detail: 'name selector "deploy" affects 2 distinct instances', affectedCount: 2 },
        ],
        enumerated: 4,
        required: 5,
        unknownSources: ["USER"],
      });
      return { result: resolveCodexAudit(poc) };
    }
    case "x06": {
      const poc = codexResult({
        caseId: "x06",
        skills: [
          codexSkill({ name: "deploy-a", scope: "REPO", logicalName: "deploy", content: "same-content" }),
          codexSkill({ name: "deploy-b", scope: "USER", logicalName: "deploy", content: "same-content" }),
        ],
        findings: [
          { id: "SAME_NAME_COLLISION", severity: "P2", sourceScope: "GLOBAL", status: "CONFIRMED", detail: 'two instances share logical name "deploy"' },
          { id: "DUPLICATE_CONTENT", severity: "P2", sourceScope: "GLOBAL", status: "CONFIRMED", detail: "two instances carry identical content" },
        ],
      });
      return { result: resolveCodexAudit(poc) };
    }
    case "x07": {
      const poc = codexResult({
        caseId: "x07",
        skills: [codexSkill({ name: "release", scope: "REPO" })],
        findings: [
          { id: "FAIL_OPEN_CONFIG", severity: "P1", sourceScope: "GLOBAL", status: "CONFIRMED", detail: "config unreadable; host fails open" },
        ],
      });
      return { result: resolveCodexAudit(poc) };
    }
    case "x08": {
      const poc = codexResult({
        caseId: "x08",
        skills: [codexSkill({ name: "release", scope: "REPO" })],
      });
      const discovery: DiscoveryInput[] = [
        { sourceScope: "REPO", skipped: [{ path: "link/SKILL.md", reason: "SYMLINK_OUTSIDE_ROOT" }] },
      ];
      return { result: resolveCodexAudit(poc, undefined, discovery) };
    }
    case "x09": {
      const native: ClaudePocResult = {
        profileId: "x09",
        engine: "claude-code",
        instances: [
          contractInstance({ engine: "claude-code", sourceRootId: "enterprise", sourceScope: "ENTERPRISE", name: "ent-admin" }),
        ],
        findings: [],
        coverage: { enumeratedSources: 3, requiredSources: 3, unknownScopes: [] },
        status: "PASS",
      };
      return { result: resolveClaudeAudit(native, { forbiddenScopes: ["ENTERPRISE"] }) };
    }
    case "x10": {
      const native: OpenMausBotPocResult = {
        profileId: "x10",
        botId: "bot-x10",
        engine: "openmausbot",
        instances: [
          contractInstance({ engine: "openmausbot", sourceRootId: "bot", sourceScope: "BOT_ASSIGNED", name: "helper" }),
        ],
        findings: [],
        coverage: { enumeratedSources: 2, requiredSources: 2, unknownScopes: [] },
        status: "PASS",
        flags: { claudeUserSkills: true, skillsLibrary: true, configSource: "file" },
      };
      return { result: resolveOpenMausBotAudit(native, { forbiddenNames: ["ghost"] }) };
    }
    case "x11": {
      const poc = codexResult({
        caseId: "x11",
        skills: [
          codexSkill({ name: "deploy", scope: "PLUGIN" }),
          codexSkill({ name: "release", scope: "REPO" }),
        ],
      });
      return { result: resolveCodexAudit(poc, { forbiddenScopes: ["PLUGIN"], allowedScopes: ["REPO"] }) };
    }
    case "x12": {
      const poc = codexResult({
        caseId: "x12",
        skills: [
          codexSkill({ name: "deploy", scope: "PLUGIN", status: "DISABLED" }),
          codexSkill({ name: "notes", scope: "USER" }),
        ],
      });
      return { result: resolveCodexAudit(poc, { forbiddenScopes: ["PLUGIN"] }) };
    }
    case "x13": {
      const poc = codexResult({
        caseId: "x13",
        skills: [
          codexSkill({ name: "acme-deploy", scope: "PLUGIN", logicalName: "acme:deploy" }),
          codexSkill({ name: "notes", scope: "USER" }),
        ],
      });
      return { result: resolveCodexAudit(poc, { forbiddenNames: ["acme"] }) };
    }
    default:
      throw new Error(`unknown extended case ${caseId}`);
  }
}

// --------------------------------------------------------------- the comparison ---

function projectResult(result: AuditResult): {
  status: string;
  findings: Array<{ id: string; severity: string; sourceScope: string; status: string; instanceIds: string[]; affectedCount: number | null }>;
  policy: { applied: boolean; effectiveCount: number; expectedCount: number; violationCount: number };
  coverage: { enumeratedSources: number; requiredSources: number; unknownScopes: string[] };
  instanceCount: number;
} {
  const findings = result.findings
    .map((f) => ({
      id: f.id,
      severity: f.severity,
      sourceScope: f.sourceScope,
      status: f.status,
      instanceIds: [...f.instanceIds],
      affectedCount: f.affectedCount ?? null,
    }))
    .sort(
      (a, b) =>
        (a.id < b.id ? -1 : a.id > b.id ? 1 : 0) ||
        (a.sourceScope < b.sourceScope ? -1 : a.sourceScope > b.sourceScope ? 1 : 0) ||
        (a.status < b.status ? -1 : a.status > b.status ? 1 : 0) ||
        (a.instanceIds.join(",") < b.instanceIds.join(",") ? -1 : a.instanceIds.join(",") > b.instanceIds.join(",") ? 1 : 0),
    );
  return {
    status: result.status,
    findings,
    policy: {
      applied: result.policy.applied,
      effectiveCount: result.policy.effectiveCount,
      expectedCount: result.policy.expectedCount,
      violationCount: result.policy.violationCount,
    },
    coverage: {
      enumeratedSources: result.coverage.enumeratedSources,
      requiredSources: result.coverage.requiredSources,
      unknownScopes: [...result.coverage.unknownScopes],
    },
    instanceCount: result.instances.length,
  };
}

describe("extended kernel golden (hand-derived, 13 cases)", () => {
  it("the expected file carries the frozen seed and 13 cases", () => {
    expect(expectedDoc.seed).toBe("P023-SKILLSCOPE-S0-2026-11-13");
    expect(expectedDoc.cases).toHaveLength(13);
    for (const c of expectedDoc.cases) {
      expect(expectedById.get(c.case_id)).toBe(c);
    }
  });

  for (const c of expectedDoc.cases) {
    it(`extended ${c.case_id} (${c.engine}): ${c.description}`, () => {
      const { result } = runCase(c.case_id);
      expect(result.schema).toBe("skillscope.audit-result/v1");
      expect(projectResult(result)).toEqual(c.expected);
      // Detail text is not frozen, but it must exist and be non-empty:
      // a finding without an explanation is a producer bug.
      for (const f of result.findings) {
        expect(typeof f.detail).toBe("string");
        expect(f.detail.length).toBeGreaterThan(0);
      }
    });
  }
});
